ENTRY(cpu_switch)
        /* Store the new curthread */
        sd      a1, PC_CURTHREAD(tp)
        /* And the new pcb */
        ld      x13, TD_PCB(a1)
        sd      x13, PC_CURPCB(tp)

struct pcb {
        uint64_t        pcb_ra;
        uint64_t        pcb_sp;
        uint64_t        pcb_gp;
        uint64_t        pcb_tp;
        uint64_t        pcb_s[12];
